// propertyWidth is the size of a packed property: the byte fields and the six
// uint16 fields, in the order of Property.
const propertyWidth = 27

// properties is the table decoded once at start: a few microseconds.
var properties = decodeProperties(propertiesData)

func decodeProperties(s string) []Property {
	ps := make([]Property, len(s)/2/propertyWidth)
	for i := range ps {
		base := i * propertyWidth
		r := func(o int) byte { return byteAt(s, base+o) }
		u16 := func(o int) uint16 { return uint16(r(o)) | uint16(r(o+1))<<8 }
		ps[i] = Property{
			Category: int16(r(0)), CombiningClass: int16(r(1)), BidiClass: int16(r(2)), DecompType: int16(r(3)),
			DecompSeq: u16(4), CasefoldSeq: u16(6), UpperSeq: u16(8), LowerSeq: u16(10), TitleSeq: u16(12),
			CombIndex: u16(14), CombLength: r(16), CombIsSecond: r(17), BidiMirrored: r(18), CompExclusion: r(19),
			Ignorable: r(20), ControlBoundary: r(21), Charwidth: r(22), AmbiguousWidth: r(23), Pad: r(24),
			BoundClass: r(25), IndicConjunctBreak: r(26),
		}
	}
	return ps
}
